(() => {
  'use strict';
  const cafes = window.MATCHA_CAFES || [];
  const $ = (s, parent = document) => parent.querySelector(s);
  const $$ = (s, parent = document) => [...parent.querySelectorAll(s)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const read = (key, fallback = []) => {try { const v=JSON.parse(localStorage.getItem(key)); return Array.isArray(v) ? v : fallback; } catch {return fallback;}};
  const write = (key, value) => {try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { toast('Your browser could not save this. Free some storage and try again.'); return false; }};
  const uid = () => typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
  let saved = read('matcha.saved.v1').filter(id => cafes.some(c => c.id === id));
  let currentCafe = 'hareruya-pantry';
  let toastTimer;
  const dialog = $('#site-dialog');
  const dialogContent = $('#dialog-content');
  let lastDialogFocus;
  function toast(message) {const el=$('#toast'); if(!el)return; el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
  function openDialog(markup) {lastDialogFocus=document.activeElement;dialogContent.innerHTML=markup;if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>{$('input,textarea,select',dialogContent)?.focus();});}
  function closeDialog(){dialog.close();lastDialogFocus?.focus();}
  $('.dialog-close')?.addEventListener('click', closeDialog);
  dialog?.addEventListener('click', e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
  dialog?.addEventListener('close',()=>lastDialogFocus?.focus());
  const cafeURL = cafe => './cafe-spotlight.html?cafe=' + encodeURIComponent(cafe.id);
  function syncSaved(){
    $$('.saved-count').forEach(el=>el.textContent=saved.length);
    $$('[data-save]').forEach(button=>{const c=cafes.find(c=>c.id===button.dataset.save);const yes=saved.includes(button.dataset.save);button.setAttribute('aria-pressed',String(yes));button.setAttribute('aria-label',(yes?'Unsave ':'Save ')+(c?.name||'café'));const label=$('[data-save-label]',button);if(label)label.textContent=yes?'Saved':'Save café';});
    const favorite=$('#favorite-btn');if(favorite){favorite.setAttribute('aria-pressed',String(saved.includes(currentCafe)));favorite.dataset.save=currentCafe;$('#favorite-count').textContent=saved.includes(currentCafe)?'Saved to your list':'Save café';}
  }
  function toggleSave(id){const next=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];if(write('matcha.saved.v1',next)){saved=next;syncSaved();toast(saved.includes(id)?'Café saved to your list.':'Café removed from your list.');}}
  function result(c,remove=false){return `<div class="search-result"><a href="${cafeURL(c)}"><img src="${esc(c.image)}" alt="${esc(c.name)}"><span><strong>${esc(c.name)}</strong><small>${esc(c.suburb)} · ${esc(c.price)} · ${esc(c.intensity)}</small></span></a><button class="icon-button" type="button" data-save="${esc(c.id)}" aria-label="${remove?'Unsave':'Save'} ${esc(c.name)}" aria-pressed="${saved.includes(c.id)}"><span class="material-symbols-outlined" aria-hidden="true">bookmark</span></button></div>`;}
  function openSaved(){openDialog(`<p class="eyebrow">Your next little ritual</p><h2 class="dialog-title">Saved for a matcha day.</h2><p class="dialog-intro">Your personal shortlist is saved on this browser.</p><div id="saved-results">${saved.length?saved.map(id=>result(cafes.find(c=>c.id===id),true)).join(''):'<p class="empty-results">No cafés saved yet. Tap a bookmark in the directory to start your list.</p><a class="button-primary" href="./index.html">Explore cafés ↗</a>'}</div>`);dialog.dataset.mode='saved';}
  function openSearch(){openDialog('<p class="eyebrow">Find your next cup</p><h2 class="dialog-title">A good matcha is close.</h2><input class="dialog-search" id="global-search" type="search" aria-label="Search all cafés" placeholder="Café, suburb, or a favourite drink…"><div id="global-results" aria-live="polite"></div>');dialog.dataset.mode='search';const input=$('#global-search');const render=()=>{const q=input.value.trim().toLowerCase();const found=cafes.filter(c=>[c.name,c.suburb,c.keywords,...c.menu.flat()].join(' ').toLowerCase().includes(q));$('#global-results').innerHTML=found.length?found.map(c=>result(c)).join(''):'<p class="empty-results">No cups found. Try “Carlton”, “mochi”, or “oat”.</p>';};input.addEventListener('input',render);render();}
  document.addEventListener('click',e=>{
    const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);if(dialog.open&&dialog.dataset.mode==='saved'){$('#saved-results').innerHTML=saved.length?saved.map(id=>result(cafes.find(c=>c.id===id),true)).join(''):'<p class="empty-results">Your saved list is empty. Explore the directory to find a new favourite.</p>'; }return;}
    if(e.target.closest('[data-open-saved]'))openSaved();
    if(e.target.closest('[data-open-search]'))openSearch();
    if(e.target.closest('.write-review'))openReview();
    if(e.target.closest('[data-share]'))share();
    const remove=e.target.closest('[data-delete-note]');if(remove){const notes=read('matcha.notes.v1').filter(n=>n.id!==remove.dataset.deleteNote);if(write('matcha.notes.v1',notes)){renderNotes();toast('Tasting note deleted.');}}
  });
  const menuButton=$('.mobile-menu-button');menuButton?.addEventListener('click',()=>{const nav=$('#mobile-nav');nav.hidden=!nav.hidden;menuButton.setAttribute('aria-expanded',String(!nav.hidden));});
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();const input=$('#cafe-search-input');if(input){input.focus();input.scrollIntoView({block:'center',behavior:'smooth'});}else openSearch();}if(e.key==='Escape'&&$('#mobile-nav')){$('#mobile-nav').hidden=true;menuButton?.setAttribute('aria-expanded','false');}});
  function setupDirectory(){
    const input=$('#cafe-search-input');if(!input)return;
    const state={suburb:'all',price:'all',intensity:'all',dietary:[],q:''};
    const apply=()=>{let count=0;$$('.cafe-card').forEach(card=>{const yes=(state.suburb==='all'||card.dataset.suburb===state.suburb)&&(state.price==='all'||card.dataset.price===state.price)&&(state.intensity==='all'||card.dataset.intensity===state.intensity)&&state.dietary.every(d=>card.dataset.dietary.split(' ').includes(d))&&(!state.q||(card.innerText+' '+card.dataset.keywords).toLowerCase().includes(state.q));card.classList.toggle('hidden',!yes);card.classList.toggle('flex',yes);if(yes)count++;});$('#results-count').textContent=`${count} ${count===1?'Café':'Cafés'} Shown`;$('#no-results-msg').classList.toggle('hidden',count!==0);$('#no-results-msg').classList.toggle('flex',count===0);$('#clear-search-btn').classList.toggle('hidden',!state.q);};
    [['.suburb-chip','suburb'],['.price-chip','price'],['.intensity-chip','intensity']].forEach(([selector,key])=>{
      const buttons=$$(selector);buttons.forEach(button=>{button.setAttribute('aria-pressed',String(button.dataset[key]==='all'));button.addEventListener('click',()=>{state[key]=button.dataset[key];buttons.forEach(b=>{const active=b===button;b.setAttribute('aria-pressed',String(active));b.classList.toggle('bg-primary',active);b.classList.toggle('text-on-primary',active);b.classList.toggle('bg-surface-container',!active);b.classList.toggle('text-on-surface-variant',!active);b.classList.remove('bg-surface-container-high');});apply();});});
    });
    $$('[data-dietary-filter]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.dietaryFilter;state.dietary=state.dietary.includes(key)?state.dietary.filter(v=>v!==key):[...state.dietary,key];b.setAttribute('aria-pressed',String(state.dietary.includes(key)));apply();}));
    input.addEventListener('input',()=>{state.q=input.value.trim().toLowerCase();apply();});
    $('#clear-search-btn').addEventListener('click',()=>{input.value='';state.q='';apply();input.focus();});
    const reset=()=>{input.value='';state.q='';state.dietary=[];$$('[data-dietary-filter]').forEach(b=>b.setAttribute('aria-pressed','false'));$('.suburb-chip[data-suburb="all"]').click();$('.price-chip[data-price="all"]').click();$('.intensity-chip[data-intensity="all"]').click();apply();};
    $('#reset-filters-btn').addEventListener('click',reset);$('#reset-all-filters').addEventListener('click',reset);
    const query=new URLSearchParams(location.search);const suburb=query.get('suburb');if(suburb){const b=$$('.suburb-chip').find(b=>b.dataset.suburb===suburb);if(b)b.click();}apply();
  }
  function setupSpotlight(){
    if(!location.pathname.endsWith('cafe-spotlight.html'))return;
    const params=new URLSearchParams(location.search);currentCafe=params.get('cafe')||'hareruya-pantry';const c=cafes.find(c=>c.id===currentCafe);
    if(!c){$('main').innerHTML='<div class="detail-empty"><h1>This cup is still brewing.</h1><p>We could not find that café in this edition.</p><a class="button-primary" href="./index.html">Back to the directory</a></div>';return;}
    document.title=c.name+' — Matcha Melbourne';
    if(c.id!=='hareruya-pantry'){
      const main=$('main'), notice=$('.edition-note',main).outerHTML;
      main.innerHTML=notice+`<div class="detail-page"><div class="detail-breadcrumb"><a href="./index.html">Directory</a> / ${esc(c.suburb)} / ${esc(c.name)}</div><section class="detail-hero"><div><p class="eyebrow">Melbourne, one cup at a time · ${esc(c.suburb)}</p><h1>${esc(c.name)}</h1><p>${esc(c.origin)}</p><p>${esc(c.address)}</p><div class="detail-actions"><button class="button-secondary" type="button" data-save="${c.id}"><span class="material-symbols-outlined" aria-hidden="true">bookmark</span><span data-save-label>Save café</span></button><button class="button-secondary" type="button" data-share>Share ↗</button><a class="button-primary" href="${esc(c.directions)}" target="_blank" rel="noopener noreferrer">Get directions ↗</a></div></div><img src="${esc(c.image)}" alt="${esc(c.alt)}"></section><div class="detail-content"><div><section class="detail-panel"><p class="eyebrow">Something to look forward to</p><h2>Signature picks</h2>${c.menu.map(([name,price])=>`<div class="menu-line"><span>${esc(name)}</span><span>${esc(price)}</span></div>`).join('')}<p class="detail-disclaimer">Sample menu and pricing from the concept. Ask the venue for its current menu and dietary details.</p></section><div class="detail-note-heading"><h2>Your tasting notes</h2><button class="button-secondary write-review" type="button">Write a note</button></div><div id="local-review-list"></div></div><aside><section class="detail-panel"><p class="eyebrow">The little details</p><h2>Plan your visit</h2><p><strong>Neighbourhood</strong><br>${esc(c.suburb)}</p><p><strong>Matcha profile</strong><br>${esc(c.intensity==='ceremonial'?'Bitter & rich':c.intensity==='light'?'Light & creamy':'Balanced & umami')}</p><p><strong>Address</strong><br>${esc(c.address)}</p><a class="button-primary" href="${esc(c.instagram)}" target="_blank" rel="noopener noreferrer">Visit café Instagram ↗</a><p class="detail-disclaimer">Check opening hours with the venue before heading out.</p></section><a class="button-secondary" href="./matcha-map-and-suburbs.html?cafe=${c.id}">Find it on the neighbourhood map ↗</a></aside></div></div>`;
    }
    const favorite=$('#favorite-btn');if(favorite)favorite.dataset.save=currentCafe;
    $$('.menu-tab-btn').forEach(b=>b.addEventListener('click',()=>{const category=b.dataset.category;$$('.menu-tab-btn').forEach(t=>{const active=t===b;t.setAttribute('aria-pressed',String(active));t.classList.toggle('bg-primary',active);t.classList.toggle('text-on-primary',active);t.classList.toggle('bg-surface-container',!active);t.classList.toggle('text-on-surface',!active);});$$('.menu-item-card').forEach(card=>card.style.display=category==='all'||card.dataset.category===category?'flex':'none');}));
    renderNotes();
  }
  async function share(){const c=cafes.find(c=>c.id===currentCafe);const url=location.href;try{if(navigator.share){await navigator.share({title:c?.name||'Matcha Melbourne',url});return;}await navigator.clipboard.writeText(url);toast('Café link copied.');}catch(e){if(e.name!=='AbortError')openDialog(`<h2 class="dialog-title">Share this café</h2><p class="dialog-intro">Copy the link below.</p><input class="dialog-search" aria-label="Café link" readonly value="${esc(url)}">`);}}
  function openReview(){dialog.dataset.mode='review';const c=cafes.find(c=>c.id===currentCafe);const community=!!$('#submitCafeForm');openDialog(`<p class="eyebrow">Your personal tasting log</p><h2 class="dialog-title">How was your cup?</h2><p class="dialog-intro">Notes stay on this browser. They are not published to other visitors.</p><form class="dialog-form" id="review-form">${community?`<label>Café<select name="cafe">${cafes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>`:`<p>${esc(c?.name||'Your café')}</p>`}<label>Your name<input name="author" autocomplete="given-name" maxlength="60" required placeholder="First name or nickname"></label><label>Your rating<select name="rating"><option value="5">5 — Loved it</option><option value="4">4 — Really good</option><option value="3">3 — Good</option><option value="2">2 — Could be better</option><option value="1">1 — Not for me</option></select></label><label>Tasting note<textarea name="note" maxlength="1500" minlength="10" required placeholder="What did you order? How was the flavour, texture, and sweetness?"></textarea></label><button class="button-primary" type="submit">Save tasting note</button></form>`);
    $('#review-form').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target);const notes=read('matcha.notes.v1');const author=String(form.get('author')).trim(),note=String(form.get('note')).trim();if(!author||note.length<10){toast('Please add your name and a note of at least 10 characters.');return;}notes.unshift({id:uid(),cafe:form.get('cafe')||currentCafe,author,rating:Number(form.get('rating')),note,created:new Date().toISOString()});if(write('matcha.notes.v1',notes)){closeDialog();renderNotes();toast('Tasting note saved on this browser.');}});
  }
  function renderNotes(){const list=$('#local-review-list');if(!list)return;const all=!!$('#submitCafeForm');const notes=read('matcha.notes.v1').filter(n=>all||n.cafe===currentCafe);list.innerHTML=notes.length?notes.map(n=>{const c=cafes.find(c=>c.id===n.cafe);return `<article class="tasting-note"><div class="tasting-note-header"><div><h4>${esc(n.author)}</h4><small>${all?esc(c?.name)+' · ':''}${new Date(n.created).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})} · Saved on this browser</small></div><span class="rating-stars" aria-label="${n.rating} out of 5 stars">${'★'.repeat(Math.max(0,Math.min(5,n.rating)))}</span></div><p>${esc(n.note)}</p><button type="button" class="text-button" data-delete-note="${esc(n.id)}">Delete note</button></article>`;}).join(''):'<p class="empty-results">Your tasting log is waiting for its first cup.</p>';}
  function setupCommunity(){
    const form=$('#submitCafeForm');if(!form)return;let selectedPrice='2';let photos=[];let photoError=false;
    const feedback=$('#form-feedback');const setFeedback=(text,error=false)=>{feedback.textContent=text;feedback.classList.toggle('error',error);};
    const prices=$$('#priceRangePicker .price-btn');function priceSelect(value){selectedPrice=value;prices.forEach(b=>{const yes=b.dataset.price===value;b.setAttribute('aria-pressed',String(yes));b.classList.toggle('bg-primary',yes);b.classList.toggle('text-on-primary',yes);b.classList.toggle('bg-surface',!yes);b.classList.toggle('text-on-surface',!yes);const sub=$('span:last-child',b);sub?.classList.toggle('text-primary-fixed',yes);sub?.classList.toggle('text-on-surface-variant',!yes);});}prices.forEach(b=>b.addEventListener('click',()=>priceSelect(b.dataset.price)));priceSelect('2');
    $$('.faq-toggle').forEach(b=>b.addEventListener('click',()=>{const item=b.closest('.faq-item'),answer=$('.faq-answer',item),willOpen=answer.classList.contains('hidden');$$('.faq-answer').forEach(a=>a.classList.add('hidden'));$$('.faq-toggle').forEach(x=>x.setAttribute('aria-expanded','false'));$$('.faq-icon').forEach(i=>i.classList.remove('rotate-180'));if(willOpen){answer.classList.remove('hidden');b.setAttribute('aria-expanded','true');$('.faq-icon',item)?.classList.add('rotate-180');}}));
    const fileInput=$('input[type=file]',form);let photoTask=Promise.resolve();
    function thumbnail(file){return new Promise((resolve,reject)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{const scale=Math.min(1,600/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve({name:file.name,image:canvas.toDataURL('image/jpeg',.72)});};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('That image could not be opened. Please choose a JPG, PNG or WebP photo.'));};img.src=url;});}
    fileInput.addEventListener('change',()=>{const files=[...fileInput.files];photoTask=(async()=>{photoError=false;photos=[];$('#photo-previews').innerHTML='';if(files.length>3||files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024)){photoError=true;setFeedback('Choose up to 3 JPG, PNG or WebP photos, each under 5 MB.',true);return;}try{photos=await Promise.all(files.map(thumbnail));$('#photo-previews').innerHTML=photos.map(p=>`<figure><img src="${p.image}" alt="Café photo preview"><figcaption>${esc(p.name)}</figcaption></figure>`).join('');setFeedback(photos.length?`${photos.length} photo${photos.length===1?'':'s'} ready. Thumbnails will be saved locally.`:'');}catch(e){photoError=true;setFeedback(e.message,true);}})();});
    const render=()=>{const submissions=read('matcha.suggestions.v1');$('#suggestion-list').innerHTML=submissions.length?submissions.map(s=>`<article class="suggestion-item"><h4>${esc(s.venueName)}</h4><p>${esc(s.suburb)} · ${esc(s.streetAddress||'Address not added')} · ${s.photos?.length||0} photo(s)</p><p>Saved ${new Date(s.created).toLocaleDateString('en-AU')} · On this browser</p><div class="suggestion-actions"><button type="button" class="text-button" data-remove-suggestion="${esc(s.id)}">Delete suggestion</button></div></article>`).join(''):'<p class="suggestion-empty">No suggestions yet. Save a café above to start your logbook.</p>';};
    form.addEventListener('submit',async e=>{e.preventDefault();await photoTask;if(photoError)return;const fields=Object.fromEntries(new FormData(form));fields.venueName=String(fields.venueName||'').trim();if(!fields.venueName){setFeedback('Please enter the café name.',true);$('#venueName').focus();return;}const submissions=read('matcha.suggestions.v1');const record={...fields,id:uid(),price:selectedPrice,features:$$('input[type=checkbox]:checked',form).map(i=>i.parentElement.innerText.trim()),photos,created:new Date().toISOString()};submissions.unshift(record);if(write('matcha.suggestions.v1',submissions)){form.reset();photos=[];$('#photo-previews').innerHTML='';priceSelect('2');setFeedback('Saved on this browser. Download your suggestions below to share a copy.');render();}});
    $('#suggestion-list').addEventListener('click',e=>{const b=e.target.closest('[data-remove-suggestion]');if(!b)return;const next=read('matcha.suggestions.v1').filter(s=>s.id!==b.dataset.removeSuggestion);if(write('matcha.suggestions.v1',next)){render();toast('Suggestion deleted.');}});
    $('#export-suggestions').addEventListener('click',()=>{const records=read('matcha.suggestions.v1');if(!records.length){toast('Save a café suggestion first.');return;}const blob=new Blob([JSON.stringify({edition:'Matcha Melbourne preview',exported:new Date().toISOString(),suggestions:records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='matcha-melbourne-suggestions.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});render();renderNotes();
  }
  function setupMap(){
    if(!$('#atlas-filters'))return;const groups=[['all','All Melbourne'],['CBD','CBD'],['Carlton','Carlton'],['West Melbourne','West Melbourne'],['St Kilda','St Kilda']];let active='all',selected=new URLSearchParams(location.search).get('cafe')||'hareruya-pantry';if(!cafes.some(c=>c.id===selected))selected=cafes[0].id;let zoom=1;let crawlRoute=[];
    const coordinates={'little-rogue':[50,50],toris:[43,55],'hareruya-pantry':[57,24],'matcha-mylkbar':[78,80],'brother-baba-budan':[39,61],'279-victoria-st':[28,37]};
    $('#atlas-filters').innerHTML=groups.map(([value,label])=>`<button class="atlas-filter" type="button" data-atlas-filter="${value}" aria-pressed="${value==='all'}">${label} (${value==='all'?cafes.length:cafes.filter(c=>c.suburb===value).length})</button>`).join('');
    function render(){const line=$('#crawl-route-line');if(line)line.setAttribute('points',crawlRoute.map(id=>coordinates[id].join(',')).join(' '));const found=cafes.filter(c=>active==='all'||c.suburb===active);if(!found.some(c=>c.id===selected))selected=found[0]?.id;$('#atlas-count').textContent=`${found.length} cafés`;$('#atlas-list').innerHTML=found.map(c=>`<button class="atlas-venue" type="button" data-map-select="${c.id}" aria-pressed="${c.id===selected}"><img src="${esc(c.image)}" alt=""><span><strong>${esc(c.name)}</strong><small>${esc(c.suburb)} · ${esc(c.price)}</small><small>${esc(c.menu[0][0])}</small></span></button>`).join('');$('#atlas-markers').innerHTML=found.map(c=>{const xy=coordinates[c.id];return `<button type="button" class="map-marker" data-map-select="${c.id}" style="left:${xy[0]}%;top:${xy[1]}%" aria-label="Select ${esc(c.name)}" aria-pressed="${c.id===selected}">${cafes.indexOf(c)+1}</button>`;}).join('');const c=cafes.find(c=>c.id===selected);$('#map-selected').hidden=!c;if(c)$('#map-selected').innerHTML=`<p class="eyebrow">${esc(c.suburb)} · ${esc(c.price)}</p><h3>${esc(c.name)}</h3><p>${esc(c.address)}</p><p>${esc(c.menu[0][0])} · ${esc(c.menu[0][1])}</p><div class="map-selected-links"><a href="${cafeURL(c)}">Explore café ↗</a><a href="${esc(c.directions)}" target="_blank" rel="noopener noreferrer">Directions ↗</a><button class="text-button" type="button" data-save="${c.id}" style="padding:0;font-size:11px"><span data-save-label>${saved.includes(c.id)?'Saved':'Save café'}</span></button></div>`;syncSaved();}
    document.addEventListener('click',e=>{const pin=e.target.closest('[data-map-select]');if(pin){selected=pin.dataset.mapSelect;render();}const filter=e.target.closest('[data-atlas-filter]');if(filter){active=filter.dataset.atlasFilter;crawlRoute=[];$$('[data-atlas-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===filter)));$$('[data-crawl]').forEach(b=>b.setAttribute('aria-pressed','false'));$('#crawl-directions').hidden=true;render();}const crawl=e.target.closest('[data-crawl]');if(crawl){active='all';$$('[data-atlas-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.atlasFilter==='all')));$$('[data-crawl]').forEach(b=>b.setAttribute('aria-pressed',String(b===crawl)));const ids=crawl.dataset.crawl==='cbd'?['little-rogue','toris','brother-baba-budan']:['hareruya-pantry','little-rogue','toris'];selected=ids[0];crawlRoute=ids;const stops=ids.map(id=>cafes.find(c=>c.id===id));const url=new URL('https://www.google.com/maps/dir/');url.search=new URLSearchParams({api:'1',travelmode:'walking',origin:stops[0].address,destination:stops[2].address,waypoints:stops[1].address}).toString();$('#crawl-directions').href=url.href;$('#crawl-directions').hidden=false;render();toast('Walking crawl selected. Open directions to follow the route.');}});
    const scale=()=>$('#atlas-scene').style.transform=`scale(${zoom})`;$('#zoom-in').addEventListener('click',()=>{zoom=Math.min(1.8,zoom+.2);scale();});$('#zoom-out').addEventListener('click',()=>{zoom=Math.max(.8,zoom-.2);scale();});$('#zoom-reset').addEventListener('click',()=>{zoom=1;scale();});render();
  }
  setupSpotlight();setupDirectory();setupCommunity();setupMap();syncSaved();
})();
